{"command":"cat <<'EOF' > status_codes.go
package main

import (
	"fmt"
	"strconv"
	"strings"
)

type statusCodeRange struct {
	start int
	end   int // -1 if single code
}

type StatusCodeSet struct {
	ranges []statusCodeRange
}

func ParseStatusCodeSet(raw string) (*StatusCodeSet, error) {
	set := &StatusCodeSet{}
	parts := strings.Split(raw, ",")
	for _, part := range parts {
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		if strings.Contains(part, "..") {
			subParts := strings.Split(part, "..")
			if len(subParts) != 2 {
				return nil, fmt.Errorf("invalid status code range: %s", raw)
			}
			start, err1 := strconv.Atoi(strings.TrimSpace(subParts[0]))
			end, err2 := strconv.Atoi(strings.TrimSpace(subParts[1]))
			if err1 != nil || err2 != nil {
				return nil, fmt.Errorf("invalid status code range: %s", raw)
			}
			set.ranges = append(set.ranges, statusCodeRange{start: start, end: end})
		} else {
			code, err := strconv.Atoi(part)
			if err != nil {
				return nil, fmt.Errorf("invalid status code range: %s", raw)
			}
			set.ranges = append(set.ranges, statusCodeRange{start: code, end: -1})
		}
	}
	return set, nil
}

func (s *StatusCodeSet) Contains(code int) bool {
	if s == nil {
		return false
	}
	for _, r := range s.ranges {
		if r.end == -1 {
			if code == r.start {
				return true
			}
		} else {
			if code >= r.start && code < r.end {
				return true
			}
		}
	}
	return false
}
EOF"}

