{"command":"cat <<'EOF' > options.go
package main

import (
	"fmt"
	"net/http"
	"os"
	"regexp"
	"strconv"
	"strings"
)

type Options struct {
	AcceptedStatusCodes      string
	BufferSize               int
	MaxConnections           int
	MaxConnectionsPerHost    int
	MaxResponseBodySize      int
	Exclude                  []string
	Include                  []string
	FollowRobotsTxt          bool
	FollowSitemapXml         bool
	Header                   []string
	IgnoreFragments          bool
	MaxRetries               int
	DNSResolver              string
	Format                   string
	JSON                     bool
	ExperimentalVerboseJSON bool
	JUnit                    bool
	MaxRedirections          int
	RateLimit                int
	Timeout                  int
	Verbose                  bool
	Proxy                    string
	SkipTLSVerification      bool
	OnePageOnly              bool
	Color                    string
	Help                     bool
	Version                  bool

	// Parsed structures
	ParsedStatusCodes *StatusCodeSet
	ParsedHeaders     http.Header
	ExcludeRegexes    []*regexp.Regexp
	IncludeRegexes    []*regexp.Regexp
	URL               string
}

const helpText = `Usage:
  executable [options] <url>

Application Options:
      --accepted-status-codes=<codes>       Accepted HTTP response status codes
                                            (e.g. '200..300,403') (default:
                                            200..300)
  -b, --buffer-size=<size>                  HTTP response buffer size in bytes
                                            (default: 4096)
  -c, --max-connections=<count>             Maximum number of HTTP connections
                                            (default: 512)
      --max-connections-per-host=<count>    Maximum number of HTTP connections
                                            per host (default: 512)
      --max-response-body-size=<size>       Maximum response body size to read
                                            (default: 10000000)
  -e, --exclude=<pattern>...                Exclude URLs matched with given
                                            regular expressions
  -i, --include=<pattern>...                Include URLs matched with given
                                            regular expressions
      --follow-robots-txt                   Follow robots.txt when scraping
                                            pages
      --follow-sitemap-xml                  Scrape only pages listed in
                                            sitemap.xml (deprecated)
      --header=<header>...                  Custom headers
  -f, --ignore-fragments                    Ignore URL fragments
      --max-retries=<count>                 Maximum retry count for network
                                            errors (default: 0)
      --dns-resolver=<address>              Custom DNS resolver
      --format=[text|json|junit]            Output format (default: text)
      --json                                Output results in JSON (deprecated)
      --experimental-verbose-json           Include successful results in JSON
                                            (deprecated)
      --junit                               Output results as JUnit XML file
                                            (deprecated)
  -r, --max-redirections=<count>            Maximum number of redirections
                                            (default: 64)
      --rate-limit=<rate>                   Max requests per second
  -t, --timeout=<seconds>                   Timeout for HTTP requests in
                                            seconds (default: 10)
  -v, --verbose                             Show successful results too
      --proxy=<host>                        HTTP proxy host
      --skip-tls-verification               Skip TLS certificate verification
      --one-page-only                       Only check links found in the given
                                            URL
      --color=[auto|always|never]           Color output (default: auto)
  -h, --help                                Show this help
      --version                             Show version
`

func ParseOptions(args []string) (*Options, error) {
	opts := &Options{
		AcceptedStatusCodes:   "200..300",
		BufferSize:            4096,
		MaxConnections:       512,
		MaxConnectionsPerHost: 512,
		MaxResponseBodySize:   10000000,
		MaxRedirections:       64,
		Timeout:               10,
		Format:                "text",
		Color:                 "auto",
		ParsedHeaders:         make(http.Header),
	}

	var positional []string

	for i := 0; i < len(args); i++ {
		arg := args[i]
		if arg == "-h" || arg == "--help" {
			opts.Help = true
			return opts, nil
		}
		if arg == "--version" {
			opts.Version = true
			return opts, nil
		}

		if strings.HasPrefix(arg, "--") {
			name := arg[2:]
			val := ""
			hasVal := false
			if idx := strings.IndexByte(name, '='); idx != -1 {
				val = name[idx+1:]
				name = name[:idx]
				hasVal = true
			}

			switch name {
			case "accepted-status-codes":
				if !hasVal && i+1 < len(args) { i++; val = args[i] }
				opts.AcceptedStatusCodes = val
			case "buffer-size":
				if !hasVal && i+1 < len(args) { i++; val = args[i] }
				v, err := strconv.Atoi(val)
				if err != nil {
					return nil, fmt.Errorf("invalid argument for flag `-b, --buffer-size' (expected int): %v", err)
				}
				opts.BufferSize = v
			case "max-connections":
				if !hasVal && i+1 < len(args) { i++; val = args[i] }
				v, err := strconv.Atoi(val)
				if err != nil {
					return nil, fmt.Errorf("invalid argument for flag `-c, --max-connections' (expected int): %v", err)
				}
				opts.MaxConnections = v
			case "max-connections-per-host":
				if !hasVal && i+1 < len(args) { i++; val = args[i] }
				v, err := strconv.Atoi(val)
				if err != nil {
					return nil, fmt.Errorf("invalid argument for flag `--max-connections-per-host' (expected int): %v", err)
				}
				opts.MaxConnectionsPerHost = v
			case "max-response-body-size":
				if !hasVal && i+1 < len(args) { i++; val = args[i] }
				v, err := strconv.Atoi(val)
				if err != nil {
					return nil, fmt.Errorf("invalid argument for flag `--max-response-body-size' (expected int): %v", err)
				}
				opts.MaxResponseBodySize = v
			case "exclude":
				if !hasVal && i+1 < len(args) { i++; val = args[i] }
				opts.Exclude = append(opts.Exclude, val)
			case "include":
				if !hasVal && i+1 < len(args) { i++; val = args[i] }
				opts.Include = append(opts.Include, val)
			case "follow-robots-txt":
				opts.FollowRobotsTxt = true
			case "follow-sitemap-xml":
				opts.FollowSitemapXml = true
			case "header":
				if !hasVal && i+1 < len(args) { i++; val = args[i] }
				opts.Header = append(opts.Header, val)
			case "ignore-fragments":
				opts.IgnoreFragments = true
			case "max-retries":
				if !hasVal && i+1 < len(args) { i++; val = args[i] }
				v, err := strconv.Atoi(val)
				if err != nil {
					return nil, fmt.Errorf("invalid argument for flag `--max-retries' (expected int): %v", err)
				}
				opts.MaxRetries = v
			case "dns-resolver":
				if !hasVal && i+1 < len(args) { i++; val = args[i] }
				opts.DNSResolver = val
			case "format":
				if !hasVal && i+1 < len(args) { i++; val = args[i] }
				opts.Format = val
			case "json":
				opts.JSON = true
			case "experimental-verbose-json":
				opts.ExperimentalVerboseJSON = true
			case "junit":
				opts.JUnit = true
			case "max-redirections":
				if !hasVal && i+1 < len(args) { i++; val = args[i] }
				v, err := strconv.Atoi(val)
				if err != nil {
					return nil, fmt.Errorf("invalid argument for flag `-r, --max-redirections' (expected int): %v", err)
				}
				opts.MaxRedirections = v
			case "rate-limit":
				if !hasVal && i+1 < len(args) { i++; val = args[i] }
				v, err := strconv.Atoi(val)
				if err != nil {
					return nil, fmt.Errorf("invalid argument for flag `--rate-limit' (expected int): %v", err)
				}
				opts.RateLimit = v
			case "timeout":
				if !hasVal && i+1 < len(args) { i++; val = args[i] }
				v, err := strconv.Atoi(val)
				if err != nil {
					return nil, fmt.Errorf("invalid argument for flag `-t, --timeout' (expected int): %v", err)
				}
				opts.Timeout = v
			case "verbose":
				opts.Verbose = true
			case "proxy":
				if !hasVal && i+1 < len(args) { i++; val = args[i] }
				opts.Proxy = val
			case "skip-tls-verification":
				opts.SkipTLSVerification = true
			case "one-page-only":
				opts.OnePageOnly = true
			case "color":
				if !hasVal && i+1 < len(args) { i++; val = args[i] }
				opts.Color = val
			default:
				return nil, fmt.Errorf("unknown flag `%s'", name)
			}
		} else if strings.HasPrefix(arg, "-") && len(arg) > 1 {
			// Short flags, e.g. -v, -f, -r 10, -e foo, -b 4096
			flagsStr := arg[1:]
			for j := 0; j < len(flagsStr); j++ {
				ch := flagsStr[j]
				switch ch {
				case 'h':
					opts.Help = true
					return opts, nil
				case 'v':
					opts.Verbose = true
				case 'f':
					opts.IgnoreFragments = true
				case 'b', 'c', 'e', 'i', 'r', 't':
					// Flags taking value
					var val string
					if j+1 < len(flagsStr) {
						if flagsStr[j+1] == '=' {
							val = flagsStr[j+2:]
						} else {
							val = flagsStr[j+1:]
						}
						j = len(flagsStr) // consumed rest
					} else if i+1 < len(args) {
						i++
						val = args[i]
					}
					switch ch {
					case 'b':
						v, err := strconv.Atoi(val)
						if err != nil {
							return nil, fmt.Errorf("invalid argument for flag `-b, --buffer-size' (expected int): %v", err)
						}
						opts.BufferSize = v
					case 'c':
						v, err := strconv.Atoi(val)
						if err != nil {
							return nil, fmt.Errorf("invalid argument for flag `-c, --max-connections' (expected int): %v", err)
						}
						opts.MaxConnections = v
					case 'e':
						opts.Exclude = append(opts.Exclude, val)
					case 'i':
						opts.Include = append(opts.Include, val)
					case 'r':
						v, err := strconv.Atoi(val)
						if err != nil {
							return nil, fmt.Errorf("invalid argument for flag `-r, --max-redirections' (expected int): %v", err)
						}
						opts.MaxRedirections = v
					case 't':
						v, err := strconv.Atoi(val)
						if err != nil {
							return nil, fmt.Errorf("invalid argument for flag `-t, --timeout' (expected int): %v", err)
						}
						opts.Timeout = v
					}
				default:
					return nil, fmt.Errorf("unknown flag `%c'", ch)
				}
			}
		} else {
			positional = append(positional, arg)
		}
	}

	if len(positional) != 1 {
		return nil, fmt.Errorf("invalid number of arguments")
	}
	opts.URL = positional[0]

	// Format resolution
	if opts.JSON {
		opts.Format = "json"
	} else if opts.JUnit {
		opts.Format = "junit"
	}

	// Validate enum choices
	if opts.Format != "text" && opts.Format != "json" && opts.Format != "junit" {
		return nil, fmt.Errorf("Invalid value `%s' for option `--format'. Allowed values are: text, json or junit", opts.Format)
	}
	if opts.Color != "auto" && opts.Color != "always" && opts.Color != "never" {
		return nil, fmt.Errorf("Invalid value `%s' for option `--color'. Allowed values are: auto, always or never", opts.Color)
	}

	// Check JUnit + verbose incompatibility
	if opts.Format == "junit" && opts.Verbose {
		return nil, fmt.Errorf("verbose option not supported for JUnit output")
	}

	// Parse Status Codes
	scSet, err := ParseStatusCodeSet(opts.AcceptedStatusCodes)
	if err != nil {
		return nil, err
	}
	opts.ParsedStatusCodes = scSet

	// Parse Headers
	for _, h := range opts.Header {
		idx := strings.IndexByte(h, ':')
		if idx == -1 {
			return nil, fmt.Errorf("invalid header format")
		}
		key := strings.TrimSpace(h[:idx])
		val := strings.TrimSpace(h[idx+1:])
		opts.ParsedHeaders.Add(key, val)
	}

	// Compile Exclude Regexes
	for _, pattern := range opts.Exclude {
		re, err := regexp.Compile(pattern)
		if err != nil {
			return nil, fmt.Errorf("error parsing regexp: %v", err)
		}
		opts.ExcludeRegexes = append(opts.ExcludeRegexes, re)
	}

	// Compile Include Regexes
	for _, pattern := range opts.Include {
		re, err := regexp.Compile(pattern)
		if err != nil {
			return nil, fmt.Errorf("error parsing regexp: %v", err)
		}
		opts.IncludeRegexes = append(opts.IncludeRegexes, re)
	}

	return opts, nil
}
EOF"}

