	ElementIDs map[string]bool
	BaseURL    *url.URL
}

func ExtractData(pageURL *url.URL, body []byte) *ExtractedData {
	data := &ExtractedData{
		ElementIDs: make(map[string]bool),
		BaseURL:    pageURL,
	}

	currentBase := pageURL
	var links []*url.URL
	seen := make(map[string]bool)

	tokenizer := html.NewTokenizer(bytes.NewReader(body))

	for {
		tt := tokenizer.Next()
		if tt == html.ErrorToken {
			break
		}

		if tt == html.StartTagToken || tt == html.SelfClosingTagToken {
			tok := tokenizer.Token()
			tagName := strings.ToLower(tok.Data)

			var href, src, id, name string

			for _, attr := range tok.Attr {
				attrKey := strings.ToLower(attr.Key)
				val := strings.TrimSpace(attr.Val)

				if attrKey == "id" && val != "" {
					id = val
					data.ElementIDs[id] = true
				}
				if attrKey == "name" && val != "" {
					name = val
					if tagName == "a" {
						data.ElementIDs[name] = true
					}
				}
				if attrKey == "href" {
					href = val
				}
				if attrKey == "src" {
					src = val
				}
			}

			if tagName == "base" && href != "" {
				if parsedBase, err := url.Parse(href); err == nil {
					currentBase = currentBase.ResolveReference(parsedBase)
					data.BaseURL = currentBase
				}
			}

			var rawLink string
			switch tagName {
			case "a", "link":
				rawLink = href
			case "frame", "iframe", "img", "script", "source", "track":
				rawLink = src
			}

			if rawLink != "" {
				// Ignore non-http schemes like mailto:, javascript:, tel:, data:
				lower := strings.ToLower(rawLink)
				if strings.HasPrefix(lower, "mailto:") ||
					strings.HasPrefix(lower, "javascript:") ||
					strings.HasPrefix(lower, "tel:") ||
					strings.HasPrefix(lower, "data:") {
					continue
				}

				if parsedLink, err := url.Parse(rawLink); err == nil {
					resolved := currentBase.ResolveReference(parsedLink)
					if resolved.Scheme == "http" || resolved.Scheme == "https" {
						resolvedStr := resolved.String()
						if !seen[resolvedStr] {
							seen[resolvedStr] = true
							links = append(links, resolved)
						}
					}
				}
			}
		}
	}

	data.Links = links
	return data
}
