package main

import (
	"context"
	"crypto/tls"
	"errors"
	"fmt"
	"io"
	"net"
	"net/http"
	"net/url"
	"strings"
	"time"
)

type FetchResult struct {
	URL        *url.URL
	FinalURL   *url.URL
	StatusCode int
	Header     http.Header
	Body       []byte
	Error      error
	ErrString  string
}

type Client struct {
	opts       *Options
	httpClient *http.Client
}

func NewClient(opts *Options) *Client {
	transport := &http.Transport{
		TLSClientConfig: &tls.Config{
			InsecureSkipVerify: opts.SkipTLSVerification,
		},
		MaxIdleConns:        opts.MaxConnections,
		MaxIdleConnsPerHost: opts.MaxConnectionsPerHost,
	}

	if opts.Proxy != "" {
		proxyURL, err := url.Parse(opts.Proxy)
		if err == nil {
			transport.Proxy = http.ProxyURL(proxyURL)
		}
	}

	if opts.DNSResolver != "" {
		resolverAddr := opts.DNSResolver
		if !strings.Contains(resolverAddr, ":") {
			resolverAddr += ":53"
		}
		resolver := &net.Resolver{
			PreferGo: true,
			Dial: func(ctx context.Context, network, address string) (net.Conn, error) {
				d := net.Dialer{}
				return d.DialContext(ctx, "udp", resolverAddr)
			},
		}
		transport.DialContext = func(ctx context.Context, network, addr string) (net.Conn, error) {
			host, port, err := net.SplitHostPort(addr)
			if err != nil {
				return nil, err
			}
			ips, err := resolver.LookupHost(ctx, host)
			if err != nil {
				return nil, err
			}
			var lastErr error
			for _, ip := range ips {
				conn, err := net.DialTimeout("tcp", net.JoinHostPort(ip, port), 5*time.Second)
				if err == nil {
					return conn, nil
				}
				lastErr = err
			}
			if lastErr != nil {
				return nil, lastErr
			}
			return nil, fmt.Errorf("could not resolve %s", host)
		}
	}

	httpClient := &http.Client{
		Transport: transport,
		CheckRedirect: func(req *http.Request, via []*http.Request) error {
			if len(via) >= opts.MaxRedirections {
				return errors.New("too many redirections")
			}
			return nil
		},
	}

	return &Client{
		opts:       opts,
		httpClient: httpClient,
	}
}

func (c *Client) Fetch(rawURL *url.URL) *FetchResult {
	var res *FetchResult
	for retries := 0; retries <= c.opts.MaxRetries; retries++ {
		res = c.doFetch(rawURL)
		if res.Error == nil || res.ErrString == "too many redirections" || res.ErrString == "location header not set" {
			break
		}
		if retries < c.opts.MaxRetries {
			time.Sleep(100 * time.Millisecond)
		}
	}
	return res
}

func (c *Client) doFetch(rawURL *url.URL) *FetchResult {
	ctx := context.Background()
	var cancel context.CancelFunc
	if c.opts.Timeout > 0 {
		ctx, cancel = context.WithTimeout(ctx, time.Duration(c.opts.Timeout)*time.Second)
		defer cancel()
	}

	req, err := http.NewRequestWithContext(ctx, "GET", rawURL.String(), nil)
	if err != nil {
		return &FetchResult{
			URL:       rawURL,
			Error:     err,
			ErrString: err.Error(),
		}
	}

	for k, vv := range c.opts.ParsedHeaders {
		for _, v := range vv {
			req.Header.Add(k, v)
		}
	}

	resp, err := c.httpClient.Do(req)
	if err != nil {
		errStr := err.Error()
		if errors.Is(err, context.DeadlineExceeded) || strings.Contains(errStr, "Client.Timeout exceeded") || strings.Contains(errStr, "context deadline exceeded") {
			errStr = "timeout"
		} else if strings.Contains(errStr, "too many redirections") {
			errStr = "too many redirections"
		} else if strings.Contains(errStr, "location header not set") {
			errStr = "location header not set"
		} else {
			// Format network dialing errors if needed
			// Check if URL error wrapper present
			if urlErr, ok := err.(*url.Error); ok {
				errStr = urlErr.Err.Error()
				if netErr, ok := urlErr.Err.(*net.OpError); ok {
					if netErr.Op == "dial" {
						errStr = fmt.Sprintf("error when dialing %s: %v", rawURL.Host, netErr)
					}
				}
			}
		}
		return &FetchResult{
			URL:       rawURL,
			Error:     err,
			ErrString: errStr,
		}
	}
	defer resp.Body.Close()

	body, _ := io.ReadAll(io.LimitReader(resp.Body, int64(c.opts.MaxResponseBodySize)))

	finalURL := resp.Request.URL
	if finalURL == nil {
		finalURL = rawURL
	}

	return &FetchResult{
		URL:        rawURL,
		FinalURL:   finalURL,
		StatusCode: resp.StatusCode,
		Header:     resp.Header,
		Body:       body,
	}
}
EOF"}

