{"command":"cat <<'EOF' > robots.go
package main

import (
	"bufio"
	"bytes"
	"fmt"
	"net/url"
	"strings"
)

type RobotsChecker struct {
	disallowed []string
}

func FetchRobotsTxt(client *Client, rootURL *url.URL) (*RobotsChecker, error) {
	robotsURL := *rootURL
	robotsURL.Path = "/robots.txt"
	robotsURL.RawQuery = ""
	robotsURL.Fragment = ""

	res := client.Fetch(&robotsURL)
	if res.Error != nil {
		return nil, fmt.Errorf("failed to fetch robots.txt: %s", res.ErrString)
	}
	if res.StatusCode != 200 {
		return nil, fmt.Errorf("failed to fetch robots.txt: %d", res.StatusCode)
	}

	checker := &RobotsChecker{}
	scanner := bufio.NewScanner(bytes.NewReader(res.Body))

	inUserAgent := false
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if idx := strings.IndexByte(line, '#'); idx != -1 {
			line = strings.TrimSpace(line[:idx])
		}
		if line == "" {
			continue
		}

		parts := strings.SplitN(line, ":", 2)
		if len(parts) != 2 {
			continue
		}
		key := strings.ToLower(strings.TrimSpace(parts[0]))
		val := strings.TrimSpace(parts[1])

		if key == "user-agent" {
			agent := strings.ToLower(val)
			if agent == "*" || agent == "muffet" {
				inUserAgent = true
			} else {
				inUserAgent = false
			}
		} else if inUserAgent && key == "disallow" {
			if val != "" {
				checker.disallowed = append(checker.disallowed, val)
			}
		}
	}

	return checker, nil
}

func (r *RobotsChecker) IsAllowed(targetURL *url.URL) bool {
	if r == nil {
		return true
	}
	path := targetURL.Path
	if path == "" {
		path = "/"
	}
	for _, rule := range r.disallowed {
		if strings.HasPrefix(path, rule) {
			return false
		}
	}
	return true
}
EOF"}

