{"command":"cat <<'EOF' > formatter.go
package main

import (
	"encoding/json"
	"fmt"

	"github.com/mattn/go-isatty"
)

type JSONLink struct {
	URL    string `json:"url"`
	Status int    `json:"status,omitempty"`
	Error  string `json:"error,omitempty"`
}

type JSONPage struct {
	URL   string     `json:"url"`
	Links []JSONLink `json:"links"`
}

func IsColorEnabled(colorOpt string) bool {
	switch colorOpt {
	case "always":
		return true
	case "never":
		return false
	default: // "auto"
		return isatty.IsTerminal(1) // 1 = os.Stdout.Fd()
	}
}

func FormatText(pageRes *PageResult, opts *Options) string {
	hasBroken := false
	for _, l := range pageRes.Links {
		if l.Error != "" {
			hasBroken = true
			break
		}
	}

	if !opts.Verbose && !hasBroken {
		return ""
	}

	useColor := IsColorEnabled(opts.Color)

	var out string
	if useColor {
		out += fmt.Sprintf("\x1b[33m%s\x1b[0m\n", pageRes.URL)
	} else {
		out += fmt.Sprintf("%s\n", pageRes.URL)
	}

	for _, l := range pageRes.Links {
		if !opts.Verbose && l.Error == "" {
			continue
		}
		if l.Error != "" {
			if useColor {
				out += fmt.Sprintf("\t\x1b[31m%s\x1b[0m\t%s\n", l.Error, l.URL)
			} else {
				out += fmt.Sprintf("\t%s\t%s\n", l.Error, l.URL)
			}
		} else {
			if useColor {
				out += fmt.Sprintf("\t\x1b[32m%d\x1b[0m\t%s\n", l.Status, l.URL)
			} else {
				out += fmt.Sprintf("\t%d\t%s\n", l.Status, l.URL)
			}
		}
	}

	return out
}

func FormatJSON(pageResults []PageResult, opts *Options) string {
	isVerboseJSON := opts.Verbose || opts.ExperimentalVerboseJSON

	var pages []JSONPage
	for _, p := range pageResults {
		hasBroken := false
		var links []JSONLink
		for _, l := range p.Links {
			if l.Error != "" {
				hasBroken = true
				links = append(links, JSONLink{
					URL:   l.URL,
					Error: l.Error,
				})
			} else if isVerboseJSON {
				links = append(links, JSONLink{
					URL:    l.URL,
					Status: l.Status,
				})
			}
		}

		if isVerboseJSON || hasBroken {
			if links == nil {
				links = []JSONLink{}
			}
			pages = append(pages, JSONPage{
				URL:   p.URL,
				Links: links,
			})
		}
	}

	if pages == nil {
		pages = []JSONPage{}
	}

	data, _ := json.Marshal(pages)
	return string(data) + "\n"
}

func FormatJUnit(pageResults []PageResult) string {
	out := "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<testsuites>\n"

	for _, p := range pageResults {
		total := len(p.Links)
		failures := 0
		for _, l := range p.Links {
			if l.Error != "" {
				failures++
			}
		}

		if total == 0 {
			out += fmt.Sprintf("  <testsuite name=\"%s\" tests=\"0\" failures=\"0\" skipped=\"0\"></testsuite>\n", p.URL)
			continue
		}

		out += fmt.Sprintf("  <testsuite name=\"%s\" tests=\"%d\" failures=\"%d\" skipped=\"0\">\n", p.URL, total, failures)
		for _, l := range p.Links {
			out += fmt.Sprintf("    <testcase name=\"%s\" classname=\"%s\">", l.URL, p.URL)
			if l.Error != "" {
				out += fmt.Sprintf("\n      <failure message=\"%s\"></failure>\n    ", l.Error)
			}
			out += "</testcase>\n"
		}
		out += "  </testsuite>\n"
	}

	out += "</testsuites>\n"
	return out
}
EOF"}

