{"command":"cat <<'EOF' > checker.go
package main

import (
	"fmt"
	"net/url"
	"strings"
	"sync"
)

type LinkResult struct {
	URL    string
	Status int
	Error  string
}

type PageResult struct {
	URL   string
	Links []LinkResult
}

type Checker struct {
	opts         *Options
	client       *Client
	robots       *RobotsChecker
	rootURL      *url.URL
	cache        map[string]*FetchResult
	cacheMux     sync.Mutex
	extracted    map[string]*ExtractedData
	extractedMux sync.Mutex
	sem          chan struct{}
}

func NewChecker(opts *Options, rootURL *url.URL) *Checker {
	maxConns := opts.MaxConnections
	if maxConns <= 0 {
		maxConns = 512
	}
	return &Checker{
		opts:      opts,
		client:    NewClient(opts),
		rootURL:   rootURL,
		cache:     make(map[string]*FetchResult),
		extracted: make(map[string]*ExtractedData),
		sem:       make(chan struct{}, maxConns),
	}
}

func (c *Checker) GetFetchResult(targetURL *url.URL) *FetchResult {
	keyURL := *targetURL
	keyURL.Fragment = ""
	key := keyURL.String()

	c.cacheMux.Lock()
	if res, ok := c.cache[key]; ok {
		c.cacheMux.Unlock()
		return res
	}
	c.cacheMux.Unlock()

	c.sem <- struct{}{}
	res := c.client.Fetch(&keyURL)
	<-c.sem

	c.cacheMux.Lock()
	c.cache[key] = res
	c.cacheMux.Unlock()

	// If HTTP response was successful and is HTML, extract links & element IDs
	if res.Error == nil && res.StatusCode >= 200 && res.StatusCode < 300 {
		contentType := res.Header.Get("Content-Type")
		isHTML := strings.Contains(strings.ToLower(contentType), "text/html") || contentType == ""
		if isHTML {
			data := ExtractData(res.FinalURL, res.Body)
			c.extractedMux.Lock()
			c.extracted[key] = data
			c.extractedMux.Unlock()
		}
	}

	return res
}

func (c *Checker) IsExcluded(u *url.URL) bool {
	str := u.String()
	for _, re := range c.opts.ExcludeRegexes {
		if re.MatchString(str) {
			return true
		}
	}
	if len(c.opts.IncludeRegexes) > 0 {
		matched := false
		for _, re := range c.opts.IncludeRegexes {
			if re.MatchString(str) {
				matched = true
				break
			}
		}
		if !matched {
			return true
		}
	}
	return false
}

func (c *Checker) CheckLink(targetURL *url.URL) (LinkResult, bool) {
	if c.IsExcluded(targetURL) {
		return LinkResult{}, false
	}

	res := c.GetFetchResult(targetURL)

	if res.Error != nil {
		return LinkResult{
			URL:   targetURL.String(),
			Error: res.ErrString,
		}, true
	}

	if !c.opts.ParsedStatusCodes.Contains(res.StatusCode) {
		return LinkResult{
			URL:   targetURL.String(),
			Error: fmt.Sprintf("%d", res.StatusCode),
		}, true
	}

	// Fragment check
	if targetURL.Fragment != "" && !c.opts.IgnoreFragments {
		contentType := res.Header.Get("Content-Type")
		isHTML := strings.Contains(strings.ToLower(contentType), "text/html") || contentType == ""
		if isHTML {
			keyURL := *targetURL
			keyURL.Fragment = ""
			key := keyURL.String()

			c.extractedMux.Lock()
			data := c.extracted[key]
			c.extractedMux.Unlock()

			if data != nil && !data.ElementIDs[targetURL.Fragment] {
				return LinkResult{
					URL:   targetURL.String(),
					Error: fmt.Sprintf("id #%s not found", targetURL.Fragment),
				}, true
			}
		}
	}

	return LinkResult{
		URL:    targetURL.String(),
		Status: res.StatusCode,
	}, true
}
EOF"}

