{"command":"cat <<'EOF' > main.go
package main

import (
	"fmt"
	"net/url"
	"os"
	"sort"
	"strings"
)

func main() {
	opts, err := ParseOptions(os.Args[1:])
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}

	if opts.Help {
		fmt.Print(helpText)
		os.Exit(0)
	}

	if opts.Version {
		fmt.Println("2.11.1")
		os.Exit(0)
	}

	rootURL, err := url.Parse(opts.URL)
	if err != nil || rootURL.Scheme == "" || rootURL.Host == "" {
		if err != nil {
			fmt.Fprintf(os.Stderr, "failed to fetch root page: %v\n", err)
		} else {
			fmt.Fprintf(os.Stderr, "failed to fetch root page: invalid URL %s\n", opts.URL)
		}
		os.Exit(1)
	}

	client := NewClient(opts)

	var robots *RobotsChecker
	if opts.FollowRobotsTxt {
		r, err := FetchRobotsTxt(client, rootURL)
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		robots = r
	}

	checker := NewChecker(opts, rootURL)
	checker.robots = robots

	var initialPages []*url.URL

	if opts.FollowSitemapXml {
		sitemapURLs, err := FetchSitemapXML(client, rootURL)
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		initialPages = sitemapURLs
	} else {
		// Fetch root page first to verify it works
		res := client.Fetch(rootURL)
		if res.Error != nil {
			fmt.Fprintf(os.Stderr, "failed to fetch root page: %s\n", res.ErrString)
			os.Exit(1)
		}
		if !opts.ParsedStatusCodes.Contains(res.StatusCode) {
			fmt.Fprintf(os.Stderr, "failed to fetch root page: %d\n", res.StatusCode)
			os.Exit(1)
		}
		if res.FinalURL != nil {
			rootURL = res.FinalURL
		}
		initialPages = append(initialPages, rootURL)
	}

	visitedPages := make(map[string]bool)
	var queue []*url.URL

	for _, p := range initialPages {
		pKey := *p
		pKey.Fragment = ""
		pStr := pKey.String()
		if !visitedPages[pStr] {
			visitedPages[pStr] = true
			queue = append(queue, p)
		}
	}

	var pageResults []PageResult
	hasBrokenLinks := false

	for len(queue) > 0 {
		currURL := queue[0]
		queue = queue[1:]

		currKey := *currURL
		currKey.Fragment = ""

		res := checker.GetFetchResult(&currKey)
		if res.Error != nil {
			continue
		}

		checker.extractedMux.Lock()
		data := checker.extracted[currKey.String()]
		checker.extractedMux.Unlock()

		pageRes := PageResult{
			URL: res.FinalURL.String(),
		}
		if pageRes.URL == "" {
			pageRes.URL = currURL.String()
		}

		if data != nil {
			for _, targetLink := range data.Links {
				linkRes, ok := checker.CheckLink(targetLink)
				if !ok {
					continue
				}
				if linkRes.Error != "" {
					hasBrokenLinks = true
				}
				pageRes.Links = append(pageRes.Links, linkRes)
			}
		}

		// Sort links on page alphabetically by URL
		sort.Slice(pageRes.Links, func(i, j int) bool {
			return pageRes.Links[i].URL < pageRes.Links[j].URL
		})

		pageResults = append(pageResults, pageRes)

		if opts.Format == "text" {
			txt := FormatText(&pageRes, opts)
			if txt != "" {
				fmt.Print(txt)
			}
		}

		// Queue sub-pages if recursive crawling enabled
		if !opts.OnePageOnly && data != nil {
			for _, targetLink := range data.Links {
				if targetLink.Hostname() == rootURL.Hostname() {
					if robots != nil && !robots.IsAllowed(targetLink) {
						continue
					}
					tKey := *targetLink
					tKey.Fragment = ""
					tStr := tKey.String()

					if !visitedPages[tStr] {
						// Check if target link response is HTML
						tRes := checker.GetFetchResult(&tKey)
						if tRes.Error == nil && opts.ParsedStatusCodes.Contains(tRes.StatusCode) {
							contentType := tRes.Header.Get("Content-Type")
							if strings.Contains(strings.ToLower(contentType), "text/html") || contentType == "" {
								visitedPages[tStr] = true
								queue = append(queue, &tKey)
							}
						}
					}
				}
			}
		}
	}

	if opts.Format == "json" {
		fmt.Print(FormatJSON(pageResults, opts))
	} else if opts.Format == "junit" {
		fmt.Print(FormatJUnit(pageResults))
	}

	if hasBrokenLinks {
		os.Exit(1)
	}
	os.Exit(0)
}
EOF"}

