{"command":"cat <<'EOF' > checker.go
package main

import (
	"fmt"
	"net/url"
	"strings"
	"sync"
)

type LinkResult struct {
	URL    string
	Status int
	Error  string
}

type PageResult struct {
	URL   string
	Links []LinkResult
}

type Checker struct {
	opts         *Options
	client       *Client
	robots       *RobotsChecker
	rootURL      *url.URL
	cache        map[string]*FetchResult
	cacheMux     sync.Mutex
	extracted    map[string]*ExtractedData
	extractedMux sync.Mutex
	sem          chan struct{}
}

func NewChecker(opts *Options, rootURL *url.URL) *Checker {
	maxConns := opts.MaxConnections
	if maxConns <= 0 {
		maxConns = 512
	}
	return &Checker{
		opts:      opts,
		client:    NewClient(opts),
		rootURL:   rootURL,
		cache:     make(map[string]*FetchResult),
		extracted: make(map[string]*ExtractedData),
		sem:       make(chan struct{}, maxConns),
	}
}

func (c *Checker) GetFetchResult(targetURL *url.URL) *FetchResult {
	keyURL := *targetURL
	keyURL.Fragment = ""
	key := keyURL.String()

	c.cacheMux.Lock()
	if res, ok := c.cache[key]; ok {
		c.cacheMux.Unlock()
		return res
	}
	c.cacheMux.Unlock()

	c.sem <- struct{}{}
	res := c.client.Fetch(&keyURL)
	<-c.sem

	c.cacheMux.Lock()
	c.cache[key] = res
	c.cacheMux.Unlock()

	if res.Error == nil && res.StatusCode >= 200 && res.StatusCode < 300 {
		contentType := res.Header.Get("Content-Type")
		isHTML := strings.Contains(strings.ToLower(contentType), "text/html") || contentType == ""
		if isHTML {
			data := ExtractData(res.FinalURL, res.Body)
			c.extractedMux.Lock()
			c.extracted[key] = data
			c.extractedMux.Unlock()
		}
	}

	return res
}

func (c *Checker) IsExcluded(u *url.URL) bool {
	str := u.String()
	for _, re := range c.opts.ExcludeRegexes {
		if re.MatchString(str) {
			return true
		}
	}
	if len(c.opts.IncludeRegexes) > 0 {
		matched := false
		for _, re := range c.opts.IncludeRegexes {
			if re.MatchString(str) {
				matched = true
				break
			}
		}
		if !matched {
			return true
		}
	}
	return false
}

func (c *Checker) CheckLink(targetURL *url.URL) (LinkResult, bool) {
	if c.IsExcluded(targetURL) {
		return LinkResult{}, false
	}

	res := c.GetFetchResult(targetURL)

	if res.Error != nil {
		return LinkResult{
			URL:   targetURL.String(),
			Error: res.ErrString,
		}, true
	}

	if !c.opts.ParsedStatusCodes.Contains(res.StatusCode) {
		return LinkResult{
			URL:   targetURL.String(),
			Error: fmt.Sprintf("%d", res.StatusCode),
		}, true
	}

	// Fragment check
	if targetURL.Fragment != "" && !c.opts.IgnoreFragments {
		contentType := res.Header.Get("Content-Type")
		isHTML := strings.Contains(strings.ToLower(contentType), "text/html") || contentType == ""
		if isHTML {
			keyURL := *targetURL
			keyURL.Fragment = ""
			key := keyURL.String()

			c.extractedMux.Lock()
			data := c.extracted[key]
			c.extractedMux.Unlock()

			if data != nil && !data.ElementIDs[targetURL.Fragment] {
				return LinkResult{
					URL:   targetURL.String(),
					Error: fmt.Sprintf("id #%s not found", targetURL.Fragment),
				}, true
			}
		}
	}

	return LinkResult{
		URL:    targetURL.String(),
		Status: res.StatusCode,
	}, true
}

func (c *Checker) CrawlPage(pageURL *url.URL) (*PageResult, []*url.URL) {
	pageKey := *pageURL
	pageKey.Fragment = ""

	res := c.GetFetchResult(&pageKey)
	if res.Error != nil {
		return nil, nil
	}

	c.extractedMux.Lock()
	data := c.extracted[pageKey.String()]
	c.extractedMux.Unlock()

	pageRes := &PageResult{
		URL: res.FinalURL.String(),
	}
	if pageRes.URL == "" {
		pageRes.URL = pageURL.String()
	}

	if data == nil || len(data.Links) == 0 {
		return pageRes, nil
	}

	type linkResultIndex struct {
		linkRes LinkResult
		ok      bool
	}

	ch := make(chan linkResultIndex, len(data.Links))
	for _, targetLink := range data.Links {
		go func(l *url.URL) {
			linkRes, ok := c.CheckLink(l)
			ch <- linkResultIndex{linkRes: linkRes, ok: ok}
		}(targetLink)
	}

	var subPages []*url.URL
	for i := 0; i < len(data.Links); i++ {
		r := <-ch
		if r.ok {
			pageRes.Links = append(pageRes.Links, r.linkRes)
		}
	}

	// Determine sub-pages to crawl
	if !c.opts.OnePageOnly {
		for _, targetLink := range data.Links {
			if targetLink.Hostname() == c.rootURL.Hostname() {
				if c.robots != nil && !c.robots.IsAllowed(targetLink) {
					continue
				}
				tKey := *targetLink
				tKey.Fragment = ""

				tRes := c.GetFetchResult(&tKey)
				if tRes.Error == nil && c.opts.ParsedStatusCodes.Contains(tRes.StatusCode) {
					contentType := tRes.Header.Get("Content-Type")
					if strings.Contains(strings.ToLower(contentType), "text/html") || contentType == "" {
						subPages = append(subPages, &tKey)
					}
				}
			}
		}
	}

	return pageRes, subPages
}
EOF"}

