{"command":"cat <<'EOF' > main.go
package main

import (
	"fmt"
	"net/url"
	"os"
	"strings"
	"sync"
)

func main() {
	opts, err := ParseOptions(os.Args[1:])
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}

	if opts.Help {
		fmt.Print(helpText)
		os.Exit(0)
	}

	if opts.Version {
		fmt.Println("2.11.1")
		os.Exit(0)
	}

	rootURL, err := url.Parse(opts.URL)
	if err != nil || rootURL.Scheme == "" || rootURL.Host == "" {
		if err != nil {
			fmt.Fprintf(os.Stderr, "failed to fetch root page: %v\n", err)
		} else {
			fmt.Fprintf(os.Stderr, "failed to fetch root page: invalid URL %s\n", opts.URL)
		}
		os.Exit(1)
	}

	client := NewClient(opts)

	var robots *RobotsChecker
	if opts.FollowRobotsTxt {
		r, err := FetchRobotsTxt(client, rootURL)
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		robots = r
	}

	checker := NewChecker(opts, rootURL)
	checker.robots = robots

	var initialPages []*url.URL

	if opts.FollowSitemapXml {
		sitemapURLs, err := FetchSitemapXML(client, rootURL)
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		initialPages = sitemapURLs
	} else {
		res := client.Fetch(rootURL)
		if res.Error != nil {
			fmt.Fprintf(os.Stderr, "failed to fetch root page: %s\n", res.ErrString)
			os.Exit(1)
		}
		if !opts.ParsedStatusCodes.Contains(res.StatusCode) {
			fmt.Fprintf(os.Stderr, "failed to fetch root page: %d\n", res.StatusCode)
			os.Exit(1)
		}
		if res.FinalURL != nil {
			rootURL = res.FinalURL
		}
		initialPages = append(initialPages, rootURL)
	}

	visitedMux := sync.Mutex{}
	visitedPages := make(map[string]bool)

	resultsChan := make(chan *PageResult)
	var wg sync.WaitGroup

	var crawlPageFunc func(u *url.URL)
	crawlPageFunc = func(u *url.URL) {
		defer wg.Done()

		pageKey := *u
		pageKey.Fragment = ""

		res := checker.GetFetchResult(&pageKey)
		if res.Error != nil {
			return
		}

		checker.extractedMux.Lock()
		data := checker.extracted[pageKey.String()]
		checker.extractedMux.Unlock()

		pageRes := &PageResult{
			URL: res.FinalURL.String(),
		}
		if pageRes.URL == "" {
			pageRes.URL = u.String()
		}

		if data != nil && len(data.Links) > 0 {
			type linkIndexRes struct {
				res LinkResult
				ok  bool
			}

			linkChan := make(chan linkIndexRes, len(data.Links))
			var linkWg sync.WaitGroup

			for _, targetLink := range data.Links {
				linkWg.Add(1)
				go func(l *url.URL) {
					defer linkWg.Done()

					linkRes, ok := checker.CheckLink(l)

					// Sub-page crawling check
					if !opts.OnePageOnly && l.Hostname() == rootURL.Hostname() {
						if robots == nil || robots.IsAllowed(l) {
							tKey := *l
							tKey.Fragment = ""
							tStr := tKey.String()

							visitedMux.Lock()
							if !visitedPages[tStr] {
								visitedPages[tStr] = true
								visitedMux.Unlock()

								tRes := checker.GetFetchResult(&tKey)
								if tRes.Error == nil && opts.ParsedStatusCodes.Contains(tRes.StatusCode) {
									contentType := tRes.Header.Get("Content-Type")
									if strings.Contains(strings.ToLower(contentType), "text/html") || contentType == "" {
										wg.Add(1)
										go crawlPageFunc(&tKey)
									}
								}
							} else {
								visitedMux.Unlock()
							}
						}
					}

					linkChan <- linkIndexRes{res: linkRes, ok: ok}
				}(targetLink)
			}

			go func() {
				linkWg.Wait()
				close(linkChan)
			}()

			for lr := range linkChan {
				if lr.ok {
					pageRes.Links = append(pageRes.Links, lr.res)
				}
			}
		}

		resultsChan <- pageRes
	}

	for _, p := range initialPages {
		pKey := *p
		pKey.Fragment = ""
		pStr := pKey.String()
		visitedPages[pStr] = true

		wg.Add(1)
		go crawlPageFunc(p)
	}

	go func() {
		wg.Wait()
		close(resultsChan)
	}()

	var pageResults []PageResult
	hasBrokenLinks := false

	for pageRes := range resultsChan {
		for _, l := range pageRes.Links {
			if l.Error != "" {
				hasBrokenLinks = true
			}
		}
		pageResults = append(pageResults, *pageRes)

		if opts.Format == "text" {
			txt := FormatText(pageRes, opts)
			if txt != "" {
				fmt.Print(txt)
			}
		}
	}

	if opts.Format == "json" {
		fmt.Print(FormatJSON(pageResults, opts))
	} else if opts.Format == "junit" {
		fmt.Print(FormatJUnit(pageResults))
	}

	if hasBrokenLinks {
		os.Exit(1)
	}
	os.Exit(0)
}
EOF

