package main

import (
	"encoding/xml"
	"fmt"
	"net/url"
)

type SitemapURLSet struct {
	URLs []struct {
		Loc string `xml:"loc"`
	} `xml:"url"`
}

func FetchSitemapXML(client *Client, rootURL *url.URL) ([]*url.URL, error) {
	sitemapURL := *rootURL
	sitemapURL.Path = "/sitemap.xml"
	sitemapURL.RawQuery = ""
	sitemapURL.Fragment = ""

	res := client.Fetch(&sitemapURL)
	if res.Error != nil {
		return nil, fmt.Errorf("failed to fetch root page: %s", res.ErrString)
	}
	if res.StatusCode == 404 {
		return nil, fmt.Errorf("failed to fetch root page: 404")
	}
	if res.StatusCode != 200 {
		return nil, fmt.Errorf("failed to GET sitemap.xml: %d", res.StatusCode)
	}

	var urlset SitemapURLSet
	if err := xml.Unmarshal(res.Body, &urlset); err != nil {
		return nil, fmt.Errorf("failed to fetch root page: %v", err)
	}

	var urls []*url.URL
	for _, u := range urlset.URLs {
		if parsed, err := url.Parse(u.Loc); err == nil {
			urls = append(urls, parsed)
		}
	}

	return urls, nil
}
EOF

